<template><div><div class="toolbar"><h3>运行状态</h3><el-button @click="load">刷新</el-button></div><el-table :data="items" border><el-table-column prop="name" label="名称"/><el-table-column prop="connectionCode" label="编码"/><el-table-column label="连接状态"><template #default="{row}"><el-tag :type="row.connected?'success':'danger'">{{row.connected?'已连接':'未连接'}}</el-tag></template></el-table-column><el-table-column prop="reconnectCount" label="重连次数"/><el-table-column prop="lastConnectedAt" label="最后连接时间"/><el-table-column prop="lastError" label="最后错误"/></el-table></div></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import http from '../../api/http'; const items=ref<any[]>([]); async function load(){const {data}=await http.get('/mqtt/status');items.value=data;} onMounted(load);</script>
